     1	//! Edge HTTP primitives shared by the CDN edge fleet.
     2	//!
     3	//! `http-core` wraps the low-level framing in [`netframe`] with the request-line,
     4	//! header-block, and chunked-body helpers the edge proxies depend on. HPACK
     5	//! decoding for HTTP/2 is delegated to `netframe`.
     6	
     7	use bytes::Bytes;
     8	use netframe::hpack;
     9	
    10	pub const MAX_HEADER_BLOCK: usize = 16 * 1024;
    11	
    12	/// A parsed HTTP/1.1 request line.
    13	#[derive(Debug, Clone, PartialEq, Eq)]
    14	pub struct RequestLine {
    15	    pub method: String,
    16	    pub target: String,
    17	    pub version: String,
    18	}
    19	
    20	/// Parse the request line (`METHOD SP request-target SP HTTP-version`).
    21	pub fn parse_request_line(line: &str) -> Option<RequestLine> {
    22	    let mut it = line.trim_end_matches(['\r', '\n']).splitn(3, ' ');
    23	    let method = it.next()?.to_string();
    24	    let target = it.next()?.to_string();
    25	    let version = it.next()?.to_string();
    26	    if method.is_empty() || target.is_empty() || !version.starts_with("HTTP/") {
    27	        return None;
    28	    }
    29	    Some(RequestLine { method, target, version })
    30	}
    31	
    32	/// Decode an HTTP/2 header block via netframe's HPACK decoder, rejecting blocks
    33	/// larger than [`MAX_HEADER_BLOCK`] before handing them to the decoder.
    34	pub fn decode_header_block(block: &[u8]) -> Result<Vec<(String, String)>, &'static str> {
    35	    if block.len() > MAX_HEADER_BLOCK {
    36	        return Err("header block too large");
    37	    }
    38	    hpack::Decoder::new()
    39	        .decode(block)
    40	        .map_err(|_| "invalid header block")
    41	}
    42	
    43	/// Reassemble an HTTP/1.1 chunked transfer-encoded body into a contiguous buffer.
    44	pub fn decode_chunked(mut input: &[u8]) -> Option<Bytes> {
    45	    let mut out = Vec::new();
    46	    loop {
    47	        let nl = input.iter().position(|&b| b == b'\n')?;
    48	        let size = usize::from_str_radix(
    49	            std::str::from_utf8(&input[..nl]).ok()?.trim(),
    50	            16,
    51	        )
    52	        .ok()?;
    53	        input = &input[nl + 1..];
    54	        if size == 0 {
    55	            return Some(Bytes::from(out));
    56	        }
    57	        out.extend_from_slice(input.get(..size)?);
    58	        input = input.get(size + 2..)?; // skip trailing CRLF
    59	    }
    60	}
